import{_ as a,o as e,c as o,ag as d}from"./chunks/framework.CAXxHpAX.js";const s=JSON.parse('{"title":"仁","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-仁.md","filePath":"50-概念资料/dict-仁.md","lastUpdated":1778155802000}'),r={name:"50-概念资料/dict-仁.md"};function l(i,t,h,u,c,n){return e(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="仁" tabindex="-1">仁 <a class="header-anchor" href="#仁" aria-label="Permalink to &quot;仁&quot;">​</a></h1><blockquote><p>传统：儒家 | 佛家对应：慈悲 | 道家对应：上善</p></blockquote><h2 id="了空居士的定义" tabindex="-1">了空居士的定义 <a class="header-anchor" href="#了空居士的定义" aria-label="Permalink to &quot;了空居士的定义&quot;">​</a></h2><p>&quot;仁&quot;就是<strong>爱人如己</strong>。了空居士不抽象讲&quot;仁&quot;，而是从天人合一的角度来解释——因为万物同体，所以爱人就是爱己，帮人就是帮己。这不是道德要求，而是&quot;同体&quot;的自然流露。</p><p>仁的日常表现就是&quot;与人为善&quot;——在哪里都要这样。它是所有善行的起点，也是心能安静的基础。</p><h2 id="原话出处" tabindex="-1">原话出处 <a class="header-anchor" href="#原话出处" aria-label="Permalink to &quot;原话出处&quot;">​</a></h2><blockquote><p>&quot;与人为善——在哪里都要这样。这是心能安静的基础。&quot; — 答疑精选</p></blockquote><blockquote><p>&quot;无缘大慈，同体大悲——因为众生与我同体，慈悲是自然的而非勉强的。&quot; — 答疑专辑2014_佛道</p></blockquote><blockquote><p>&quot;圣人无常心，以百姓心为心——真正有智慧的人没有自己的私心，以大家的利益为利益。&quot; — 道德经讲解</p></blockquote><h2 id="常见误解" tabindex="-1">常见误解 <a class="header-anchor" href="#常见误解" aria-label="Permalink to &quot;常见误解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>正解</th></tr></thead><tbody><tr><td>仁就是做好事</td><td>仁是心态——发自内心为别人好，不是刻意&quot;做&quot;出来的</td></tr><tr><td>仁和利己冲突</td><td>了空居士说利人就是利己（同体观），两者本来不二</td></tr></tbody></table><h2 id="跨传统对比" tabindex="-1">跨传统对比 <a class="header-anchor" href="#跨传统对比" aria-label="Permalink to &quot;跨传统对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>传统</th><th>对应概念</th><th>侧重</th></tr></thead><tbody><tr><td>儒家</td><td>仁</td><td>推己及人的爱，从亲到疏层层扩展</td></tr><tr><td>佛家</td><td>慈悲</td><td>无缘大慈同体大悲，基于众生一体</td></tr><tr><td>道家</td><td>上善若水</td><td>利万物而不争</td></tr></tbody></table><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-恕">dict-恕</a> — 恕（己所不欲勿施于人）是行仁的底线方法</li><li><a href="/50-概念资料/dict-敬">dict-敬</a> — 恭敬心是仁在待人中的体现</li><li><a href="/50-概念资料/dict-家庭道场">dict-家庭道场</a> — 仁的开始：从对家人的爱开始修</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-天人合一">model-天人合一</a> — 万物同体是仁的本体论基础</li><li><a href="/10-核心模型/model-历境炼心">model-历境炼心</a> — 在与人的每一次交往中践行仁</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><p>每天找一个机会主动帮助别人——不挑对象，不求回报。帮了就放下，只是觉得自己做了该做的事。</p>',19)])])}const b=a(r,[["render",l]]);export{s as __pageData,b as default};
